"""Deterministic authored lessons. No runtime code generation or paid services."""
import copy
import importlib.util
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]

def load_fractions():
    spec=importlib.util.spec_from_file_location('fraction_lessons',HERE.parent/'fractions-local/lessons.py')
    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    lessons=copy.deepcopy(mod.LESSONS)
    intros=[
      'Would you choose three quarters of a pizza, or one half? Today we are comparing and ordering fractions. We will build equal-sized wholes, look carefully at the pieces, and use a number line to explain which amount is bigger. What do you predict?',
      'Can a fraction change its name without changing its size? Today we are exploring equivalent fractions. We will split and regroup equal parts, then check our thinking with pictures. Could one half really be the same amount as four eighths?',
      'What happens when the amount is bigger than one whole? Today we are exploring mixed numbers and improper fractions. We will build the wholes, count the extra pieces, and connect two ways of naming exactly the same amount. Ready to investigate?',
      'How can we add pieces when the pieces have different names? Today we are adding and subtracting fractions. We will use equal-sized wholes and rename parts when we need to. What should happen to the size of the pieces when we combine them?',
      'A recipe needs one half of a cup of oats and one quarter of a cup of nuts. How much goes into the bowl altogether? Today we are solving fraction problems by modelling the situation, choosing an operation, and checking whether our answer makes sense.'
    ]
    for lesson,intro in zip(lessons,intros):
        lesson['topic']='fractions'; lesson['beats'][0]['text']=intro
        for b in lesson['beats']:
            b['role']='explanation'
            if 'Try this:' in b['text'] or 'Your turn' in b['chapter'] or 'Try one' in b['text']:
                b['pause']=4; b['role']='question'
        # Ensure every film includes an unrevealed question followed by a separate answer.
        questions={
          'comparing':('Which is greater, five eighths or three eighths?',[[5,8],'?', [3,8]],'Five eighths is greater: the same-sized parts are being counted.'),
          'equivalent':('Is six eighths equivalent to three quarters?',[[6,8],'?', [3,4]],'Yes. Dividing both six and eight by two gives three quarters.'),
          'mixed':('How many wholes and quarters are in nine quarters?',[[9,4],'=','?'],'Nine quarters is two wholes and one quarter.'),
          'addsub':('What is two thirds minus one sixth?',[[2,3],'−',[1,6],'=','?'],'Two thirds is four sixths. Four sixths minus one sixth is three sixths, or one half.'),
          'problems':('You walk two thirds of a kilometre, then one sixth more. How far is that altogether?',[[2,3],'+',[1,6],'=','?'],'Two thirds is four sixths. Adding one sixth gives five sixths of a kilometre.')}
        # Remove the old practice prompt before adding the dedicated question/answer.
        lesson['beats']=[b for b in lesson['beats'] if b['chapter']!='Your turn' and not b['text'].startswith('Your turn:')]
        recaps={
          'comparing':'Compare equal wholes. When pieces have the same size, compare their counts. Use a number line to order fractions from left to right.',
          'equivalent':'Equivalent fractions name the same amount. Multiply or divide both numbers by the same non-zero factor. A model or number line helps you check that the value stays unchanged.',
          'mixed':'Group equal fractional parts to make wholes, then keep the remainder as a fraction. Mixed numbers and improper fractions are two ways to name the same amount.',
          'addsub':'Use the same-sized whole and same-sized parts. Rename fractions when needed, combine or remove parts, and check the size of the result. Shared-denominator methods beyond related denominators are extension work.',
          'problems':'Identify the whole, model the relationship, and choose an operation from the story. Rename to equal-sized parts, calculate carefully, and check the answer with its unit.'}
        lesson['beats'][-1]['text']=recaps[lesson['id']]
        q,eq,a=questions[lesson['id']]
        template=dict(chapter='Think it through',equation=eq,rows=[],line=None,area=None,context=None,note='Take four seconds to think.',text=q,pause=4,role='question')
        lesson['beats'].insert(-1,template)
        lesson['beats'].insert(-1,dict(template,text=a,chapter='Let’s check',pause=1,role='answer',note='Explain why your answer makes sense.'))
        # Do not display a question equation during its answer.
        answers={'comparing':[[5,8],'>',[3,8]],'equivalent':[[6,8],'=',[3,4]],'mixed':[[9,4],'=',[2,1,4]],'addsub':[[2,3],'−',[1,6],'=',[1,2]],'problems':[[2,3],'+',[1,6],'=',[5,6]]}
        lesson['beats'][-2]['equation']=answers[lesson['id']]
        lesson['beats'][0]['role']='opening'; lesson['beats'][-1]['role']='recap'
        lesson['id']='fractions-'+lesson['id']
        lesson['file']='MathMagic_V2_'+lesson['id'].replace('-','_')
    return lessons

def beat(text,chapter,equation=None,board=None,**extra):
    return dict(text=text,chapter=chapter,equation=equation or [],board=board or [],rows=[],line=None,area=None,context=None,note='',role='explanation',**extra)

def generic(topic,section,title,opening,concept,examples,question,answer,recap):
    """Examples contain two narrated steps and corresponding progressive boards."""
    b=[beat(opening,'Let’s investigate',role_override='opening'),beat(concept,'Build the idea')]
    b[0].pop('role_override'); b[0]['role']='opening'
    for i,(n1,v1,n2,v2) in enumerate(examples,1):
        b.extend([beat(n1,f'Example {i}: plan',board=v1),beat(n2,f'Example {i}: explain',board=v2)])
    q,visual=question; a,av=answer
    b.extend([beat(q,'Your turn',board=visual,pause=4),beat(a,'Let’s check',board=av),beat(recap,'What to remember')])
    b[-3]['role']='question'; b[-2]['role']='answer'; b[-1]['role']='recap'
    return dict(id=topic+'-'+section,topic=topic,section=section,title=title,file='MathMagic_V2_'+(topic+'_'+section).replace('-','_'),beats=b)

def load_whole():
    lessons=[]
    questions=[('In 583,214, what is the value of the eight?','583,214: value of 8 = ?', 'The eight is in the ten-thousands place. Its value is eighty thousand.','8 × 10,000 = 80,000'),('What number is six hundred thousand plus twenty thousand plus four thousand plus three hundred plus eight?','600,000 + 20,000 + 4,000 + 300 + 8 = ?', 'The total is six hundred and twenty-four thousand, three hundred and eight. There are zero tens.','624,308'),('Which is greater: 582,430 or 582,403?','582,430 ? 582,403','The first differing place is the tens. Three tens is greater than zero tens, so 582,430 is greater.','582,430 > 582,403'),('What is the value of the eight in 5.218?','5.218: value of 8 = ?', 'The eight is in the thousandths place, so it represents eight thousandths.','8 thousandths = 0.008'),('Which is greater: 2.405 or 2.45?','2.405 ? 2.45', 'Write 2.45 as 2.450. At the hundredths place, five hundredths is greater than zero hundredths.','2.450 > 2.405')]
    for src,q in zip(json.loads((HERE.parent/'whole-numbers/lessons.json').read_text()),questions):
        beats=[]
        for i,s in enumerate(src['scenes']):
            text=s['narration']
            if i==0: text='Today we are investigating '+src['title'].lower()+'. '+text
            beats.append(beat(text,s['heading'],board=[r['text'] for r in s['rows']],model=s.get('model')))
        beats[0]['role']='opening'
        beats.insert(-1,beat(q[0],'Your turn',board=[q[1]],pause=4)); beats[-2]['role']='question'
        beats.insert(-1,beat(q[2],'Let’s check',board=[q[3]])); beats[-2]['role']='answer'; beats[-1]['role']='recap'
        lessons.append(dict(id='whole-numbers-'+src['id'],topic='whole-numbers',section=src['id'],title=src['title'],file='MathMagic_V2_whole_numbers_'+src['id'],beats=beats))
    return lessons

