        [('Read four point three zero seven. The four represents four ones, the three represents three tenths, and the seven represents seven thousandths. There are no hundredths.',['4.307','4 ones + 3 tenths + 0 hundredths + 7 thousandths'], 'The zero keeps the seven in the thousandths place. Without that zero, four point three seven would have seven hundredths, a different amount.',['4.307 ≠ 4.37','7 thousandths = 0.007']),('Find the value of the six in twelve point zero six four. The six is the second digit after the decimal point.',['12.064','tenths: 0 | hundredths: 6 | thousandths: 4'], 'The six represents six hundredths, or zero point zero six. Name the place before stating the value. It does not represent six tenths or six whole ones.',['6 hundredths = 0.06'])],
        ('What is the value of the eight in five point two one eight?', ['5.218: value of 8 = ?']),('It is eight thousandths, or zero point zero zero eight. The eight is in the third decimal place.',['8 thousandths = 0.008']),
